#!/bin/bash
# 装备外观概念 v1：gpt-image-2 high 1536x1024 x10（Rhett 11-03 15:45 要求出概念图）
cd /workspace/work/.agents/skills/credit-media-skill/credit-media-skill
export CREDIT_MEDIA_API_KEY=injected-by-gateway
O=/workspace/projects/22a18b27-6e78-4e98-99c5-6cd8a8c2cbb9/sync/CG制作/装备外观概念_v1; R=/workspace/projects/22a18b27-6e78-4e98-99c5-6cd8a8c2cbb9/sync/CG制作/keyvisual_v1
PRE="写实电影风格暗黑奇幻游戏美术概念设定图，16:9横构图，深色背景，与参考图同一世界观和画风（如有参考图）；效果须能在 Unity URP 中实现：发光遮罩材质层、GPU 粒子、地面贴花，光效克制，不过曝发白。"
NEG="画面不要出现任何文字、字母、数字、标签、水印、UI。"
gen(){ n=$1; shift; p=$1; shift; args=(); for i in "$@"; do args+=(--image "$i"); done
  bash scripts/run.sh image --model gpt-image-2 --size 1536x1024 --quality high --prompt "$PRE $p $NEG" "${args[@]}" --out $O/$n.png > $O/$n.log 2>&1 & }
gen W1_sword_tiers "游戏武器品级展示：四把单手长剑竖直并排陈列在深色石台上，同一把剑的同一造型轮廓，从左到右品级递增：第一把素铁剑、朴素磨损；第二把加铜护手和刃面蚀纹；第三把加护手中央紫色宝石和符文槽，宝石微微发光；第四把为传说品质，造型更精致繁复、金色雕纹，刃口沿符文流动橙金色光，周围少量火星。" $R/C1_warrior_v2.jpg
gen W2_staff_tiers "游戏武器品级展示：四根法杖竖直并排陈列在深色石台上，同一造型轮廓，从左到右品级递增：第一根朴素橡木杖；第二根杖头加铜箍和刻纹；第三根杖头镶紫色宝石，微光；第四根为传说品质，造型更精致、银金雕花，杖头悬浮发光的紫色晶核和两道缓慢旋转的符文环。" $R/C2_mage_v3.jpg
gen D1_rifter "独特暗金武器「裂地者」双手巨斧单品展示，斜放在焦黑岩石上：斧刃是一整块黑色熔岩岩石，表面裂缝里橙红岩浆缓慢流动发光，斧柄为烧焦铁木缠黑铁箍；斧刃下方地面被劈出一道发光裂痕，有少量火星与热浪。"
gen D2_spine "独特暗金武器「寒脊之骨」单手剑单品展示，悬浮在暗色冰窟中：剑身由骨龙脊椎骨节一节节组成，骨节间嵌着淡蓝冰晶，剑尖是锋利的骨刺，握柄缠白霜结冰，周围冷雾与飘落冰屑。"
gen D3_frostheart "独特暗金武器「霜心」魔杖单品展示，悬浮在暗色背景：杖身银白扭曲如冰枝，杖头是一块破碎的古镜，镜中隐约映出一张苍白微笑的女子面孔，几片碎镜片绕杖头缓慢旋转，泛冷蓝微光。"
gen S1_fury "按参考图中的战士重新设计为穿着全套6件「狂怒战魂」套装的全身三分之四侧视：黑铁重甲、兽骨角头盔、带三根弯骨尖刺的肩甲、暗红破布、骨饰手甲与护腕、重腿甲；整套统一配色暗红与黑铁；甲缝中有暗红到熔橙的发光熔血纹，手甲滴落余烬，背后轻微热浪，脚下石面有龟裂发光的铁血纹路。" $R/C1_warrior_v2.jpg
gen S2_frost "按参考图中的女法师重新设计为穿着全套6件「霜誓秘仪」套装的全身三分之四侧视：冰蓝镶白法袍、冰晶肩饰、霜誓兜帽、丝质手套与护腕；整套冰蓝与银白配色；左半身法袍覆盖霜花闪粉，右手掌上一簇淡蓝冷焰，几颗六角雪晶环绕，脚下石面结霜，低处冷雾。" $R/C2_mage_v3.jpg
gen S3_chrono "按参考图中的时砂行者重新设计为穿着全套6件「时痕」套装的全身三分之四侧视：深棕皮甲兜帽、肩垫、皮甲、手套、护腕、长裤，镶嵌黄铜钟表齿轮零件，背后一个小钟盘；金色细沙像沙漏一样沿身体缓缓下淌，身后两道半透明残影，脚下地面有一圈细细的十二刻度钟环光纹。" $R/C3_chrono.jpg
gen S4_alchemy "按参考图中的炼金投弹手重新设计为穿着全套6件「赤青碧」套装的全身三分之四侧视：鸟嘴面罩兜帽、披肩、长衣、手套、护腕、绑腿，腰间挂满赤、青、碧三色发光药瓶；三色药雾在腰部互相缠绕并在交汇处混色，脚边一小滩冒泡的腐蚀液。" $R/C4_alchemy.jpg
gen E1_upgrade_compare "同一名战士（严格按参考图外貌与盔甲）并排三个全身站姿对比，从左到右：左为普通状态无光效；中为全身强化+9：盔甲金属边缘细窄的橙到钢蓝淬火光、手中剑微微发橙光、身旁十来颗上升小光点、脚下淡淡细符文圈；右为全身强化+15：在中间基础上，脚下常驻一圈刻古钟铭文的金色光环、一道向外扩散的贴地冲击波环、极淡竖直光柱、肩头飘落金色余烬，地面被暖光染色。" $R/C1_warrior_v2.jpg
wait
